const find=()=>[...document.querySelectorAll('*')].filter(e=>e.children.length==0&&e.textContent.includes('HAK-5638'))[0];
let sc=[...document.querySelectorAll('*')].find(e=>e.scrollHeight>e.clientHeight+50&&getComputedStyle(e).overflowY!='visible');
let n=0;while(!find()&&n<300){sc.scrollTop+=200;await new Promise(r=>setTimeout(r,60));n++}
const f=find();if(!f)'notfound '+sc.scrollTop+'/'+sc.scrollHeight;else{f.scrollIntoView({block:'center'});let row=f;while(row&&!row.querySelector('button'))row=row.parentElement;const b=row.querySelector('button');b.textContent+'|'+row.innerText.replace(/\n/g,' ')}

